<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { Plus, Play, Pause, Square, ArrowUpRight, FlaskConical } from 'lucide-vue-next';
import type { AppModel } from '../../composables/useTradingApp';
import type { PaperSnapshot } from '../../../../main/services/paper/controller';
import type { PaperTrade } from '../../../../main/types/paper';
import ConfirmDialog from '../ConfirmDialog.vue';
import AppSelect from '../ui/AppSelect.vue';
import AppTextInput from '../ui/AppTextInput.vue';
const props = defineProps<{ model: AppModel }>();
const emit = defineEmits<{ settings: [] }>();
const state = ref<PaperSnapshot | null>(null), selectedId = ref(''), error = ref(''), busy = ref(false), creating = ref(false);
const capital = ref('1000'), calls = ref(12), tab = ref('positions'), tradeDetail = ref<PaperTrade | null>(null), endConsent = ref(false);
let request = 0; const clock = ref(Date.now());
let disposed = false, cleanup: (() => void) | void, timer: ReturnType<typeof setInterval> | undefined;
const api = window.electronAPI;
const cycles = computed(() => state.value?.cycles || []);
const cycle = computed(() => cycles.value.find(c => c.id === selectedId.value) || cycles.value[cycles.value.length - 1]);
const metrics = computed(() => { const m = cycle.value ? state.value?.metrics[cycle.value.id] : undefined; return m && m.open > 0 && clock.value-(state.value?.observedAt||0)>15000 ? {...m,equity:null,knownNetPnl:null} : m; });
const hidden = computed(() => props.model.preferences.hideAmounts);
const status = { running:'模拟运行中',paused:'已暂停开仓',settling:'旧周期待结算',archived:'已归档' };
const orderStatus = {pending:'待成交',filled:'已模拟成交',abstained:'弃权',rejected:'风控拒绝',expired:'已失效',cancelled:'已取消'};
const exitReason = {entry:'开仓',stop:'止损',target:'止盈',time:'期限退出','cycle-end':'周期结束'};
const date = (at:number) => new Date(at).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const amount = (value: string | null | undefined, signed=false) => {
  if (hidden.value) return '••••••'; if(value == null || !Number.isFinite(Number(value))) return '—';
  const n=Number(value);return `${signed && n >= 0 ? '+' : ''}${n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
};
const price = (value: string | undefined) => value == null ? '—' : hidden.value ? '••••••' : Number(value).toLocaleString('en-US',{maximumSignificantDigits:8});
const tone = (value: string | null | undefined) => hidden.value || value == null ? '' : Number(value)>0?'positive-text':Number(value)<0?'negative-text':'';
const currentPrice = (t:PaperTrade) => { const b=state.value?.books[t.symbol]; return b && clock.value-b.observedAt<=15000 ? (t.direction==='long'?b.bids:b.asks)[0][0] : undefined; };
const curve = computed(() => {
  if(!cycle.value || hidden.value) return null;
  const points=cycle.value.curve;const finite=points.filter(p=>p.equity!==null);if(finite.length<2)return null;
  const values=finite.map(p=>Number(p.equity)), low=Math.min(...values), high=Math.max(...values), spread=Math.max(high-low,Number(cycle.value.capital)*.001);
  const start=points[0].at, end=points[points.length-1].at;let pen=false,path='';
  for(const p of points) {if(p.equity===null){pen=false;continue;}const x=12+616*(p.at-start)/Math.max(1,end-start),y=105-85*(Number(p.equity)-low)/spread;path+=`${pen?'L':'M'}${x.toFixed(2)},${y.toFixed(2)} `;pen=true;}
  return {path,low,high,start,end};
});
const drawdown = computed(()=>{
  if(!cycle.value || hidden.value)return '—';let peak=Number(cycle.value.capital),dd=0;
  for(const p of cycle.value.curve){if(p.equity===null)continue;const equity=Number(p.equity);peak=Math.max(peak,equity);if(peak>0)dd=Math.max(dd,(peak-equity)/peak*100);}
  return dd.toFixed(2)+'%';
});
const activity = computed(()=>state.value?.calls.filter(c=>c.cycleId===cycle.value?.id).slice(-3).reverse()||[]);
async function load(){clock.value=Date.now();if(busy.value)return;const generation=++request;if(!api?.getPaperState){error.value='模拟服务暂不可用。';return;}try{const result=await api.getPaperState();if(disposed||generation!==request)return;if(result.success&&result.data){state.value=result.data;if(!selectedId.value)selectedId.value=result.data.cycles.at(-1)?.id||'';error.value='';}else error.value=result.error||'模拟历史读取失败，原文件保留。';}catch{if(!disposed&&generation===request)error.value='模拟历史暂不可用，请重试。';}}
async function action(run:()=>Promise<{success:boolean;data?:PaperSnapshot;error?:string}>){if(busy.value)return;++request;busy.value=true;error.value='';try{const result=await run();if(!result.success||!result.data)throw new Error();state.value=result.data;creating.value=false;endConsent.value=false;}catch{error.value='操作未完成：请检查本金、模型配置或预算。旧周期历史已保留。';}finally{busy.value=false;}}
async function start(){if(!/^(?:[1-9]\d*)(?:\.\d{1,2})?$/.test(capital.value)||Number(capital.value)<100||Number(capital.value)>1000000){error.value='请输入 100–1,000,000 之间的虚拟本金，最多两位小数。';return;}await action(()=>api!.startPaperCycle({capital:capital.value,callsPerDay:calls.value,consent:true}));if(!error.value)selectedId.value=state.value?.cycles.at(-1)?.id||'';}
async function mode(next:'running'|'paused'|'settling'){if(cycle.value)await action(()=>api!.setPaperMode(cycle.value!.id,next));}
onMounted(()=>{void load();cleanup=api?.onPaperChanged?.(()=>void load());timer=setInterval(()=>void load(),5000);});
onUnmounted(()=>{disposed=true;if(typeof cleanup==='function')cleanup();if(timer)clearInterval(timer);});
</script>
<template>
  <main class="paper-page" aria-labelledby="paper-title">
    <div class="workspace-heading"><div><p class="eyebrow">AI 策略 · 独立虚拟本金</p><h1 id="paper-title">模拟实验室</h1></div><div class="paper-actions"><AppSelect v-if="cycles.length" v-model="selectedId" label="选择模拟周期" :options="cycles.map((c,i)=>({value:c.id,label:`周期 ${String(i+1).padStart(2,'0')} · ${date(c.startedAt)}`}))"/><button class="button subtle" :disabled="busy" @click="creating=true"><Plus :size="15"/>新周期</button></div></div>
    <div v-if="error" class="research-error" role="alert">{{ error }} <button class="text-button" @click="load">重试</button><button class="text-button" @click="emit('settings')">模型配置</button></div>
    <section v-if="!cycle" class="paper-intro"><FlaskConical :size="36"/><h2>先用模拟检验判断</h2><p>设定虚拟本金，让 AI 查证候选、按规则模拟成交，留下每笔决策与成本。</p><div class="paper-steps"><span>公开市场研究</span><span>条件与风控</span><span>盘口模拟</span><span>历史复核</span></div><button class="button primary" @click="creating=true">开启第一个周期</button><small>仅 Binance USDT 永续 · 不需要交易所 Key · 不会真实下单</small></section>
    <template v-else>
      <div class="paper-status"><span class="status-pill">{{ status[cycle.status] }}</span><span>本金 {{ amount(cycle.capital) }} USDT · {{ cycle.policy.version }}</span><div class="paper-actions"><button v-if="cycle.status==='running'" class="button subtle" :disabled="busy" @click="mode('paused')"><Pause :size="14"/>暂停开仓</button><button v-if="cycle.status==='paused'" class="button subtle" :disabled="busy" @click="mode('running')"><Play :size="14"/>恢复运行</button><button v-if="['running','paused'].includes(cycle.status)" class="button subtle" :disabled="busy" @click="endConsent=true"><Square :size="13"/>结束周期</button></div></div>
      <section class="paper-kpis" aria-label="模拟周期结果"><div><span>{{ metrics?.fundingComplete ? '已核对净值' : '暂计净值' }} · USDT</span><strong>{{ amount(metrics?.equity) }}</strong></div><div><span>{{ metrics?.fundingComplete ? '已核对净盈亏' : '暂计盈亏' }}</span><strong :class="tone(metrics?.knownNetPnl)">{{ amount(metrics?.knownNetPnl,true) }}</strong><small v-if="!metrics?.fundingComplete">资金费待补齐</small></div><div><span>已观测最大回撤</span><strong>{{ drawdown }}</strong><small>仅采样点，缺口不补值</small></div><div><span>已结算 / 持仓笔数</span><strong>{{ metrics?.closed ?? '—' }} <small>/ {{ metrics?.open ?? '—' }}</small></strong></div></section>
      <div class="paper-insight"><section class="paper-chart"><div class="paper-chart-label"><h2>净值轨迹</h2><span>{{ hidden ? '已隐藏' : curve ? `${amount(String(curve.low))} – ${amount(String(curve.high))}` : '等待后续有效行情' }}</span></div><svg v-if="curve" viewBox="0 0 640 120" role="img" aria-label="本周期采样净值曲线，空缺处断线"><path :d="curve.path" fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div v-else class="paper-chart-empty">{{ hidden?'金额与曲线已隐藏':'尚无足够采样，不生成收益曲线' }}</div><div v-if="curve" class="paper-chart-label"><span>{{ date(curve.start) }}</span><span>{{ date(curve.end) }}</span></div></section><aside class="paper-agent"><h2><span :class="{'paper-pulse':state?.thinking}"/>{{ state?.thinking?'AI 正在查证':'Agent 动态' }}</h2><p v-if="!activity.length">尚无模型调用。开启后按预算查证，不保证每轮产生交易。</p><div v-for="call in activity" :key="call.id"><span>{{ date(call.at) }}</span><strong>{{ {reserved:'调用已预留',complete:'判断已记录',failed:'查证失败'}[call.status] }}</strong></div><small>近 24h 已预留 {{ state?.callsReserved24h }} / {{ cycle.policy.callsPerDay }} 次调用 · 实际费用未知</small></aside></div>
      <nav class="paper-tabs" aria-label="模拟记录分类"><button v-for="item in [{id:'positions',label:'持仓'},{id:'orders',label:'决策与订单'},{id:'trades',label:'历史成交'},{id:'calls',label:'模型调用'},{id:'gaps',label:'运行缺口'}]" :key="item.id" :aria-pressed="tab===item.id" @click="tab=item.id">{{ item.label }}</button></nav>
      <div class="paper-records">
        <template v-if="tab==='positions'||tab==='trades'"><table v-if="cycle.trades.some(t=>tab==='positions'?!t.exit:!!t.exit)" class="paper-table"><thead><tr><th scope="col">币种 / 方向</th><th scope="col">数量</th><th scope="col">开仓 / {{ tab==='positions'?'最新可见价':'平仓' }}</th><th scope="col">止损 / 止盈</th><th scope="col">已计费用 / 资金费</th><th scope="col">{{ tab==='positions'?'观察期限':'毛盈亏' }}</th><th scope="col">依据</th></tr></thead><tbody><tr v-for="trade in cycle.trades.filter(t=>tab==='positions'?!t.exit:!!t.exit)" :key="trade.id"><th scope="row">{{ trade.symbol.replace(/USDT$/,'') }}<small>{{ trade.direction==='long'?'模拟多头':'模拟空头' }}</small></th><td>{{ price(trade.entry.quantity) }}</td><td>{{ price(trade.entry.price) }}<small>{{ price(trade.exit?.price||currentPrice(trade)) }}</small></td><td>{{ price(trade.stop) }}<small>{{ price(trade.target) }}</small></td><td>{{ amount(trade.fees) }}<small>{{ amount(trade.funding,true) }}</small></td><td>{{ trade.exit?amount(trade.grossPnl,true):date(trade.dueAt) }}<small v-if="trade.exit">{{ exitReason[trade.exit.reason] }}</small></td><td><button class="icon-button" :aria-label="`查看 ${trade.symbol} 模拟成交依据`" @click="tradeDetail=trade"><ArrowUpRight :size="16"/></button></td></tr></tbody></table><div v-else class="paper-record-empty">{{ tab==='positions'?'暂无模拟持仓。条件未满足时，Agent 会保留观察。':'暂无已平仓交易。未成交与拒绝不会算成盈利样本。' }}</div></template>
        <table v-if="tab==='orders'&&cycle.decisions.length" class="paper-table"><thead><tr><th scope="col">时间 / 币种</th><th scope="col">判断逻辑</th><th scope="col">状态</th></tr></thead><tbody><tr v-for="decision in [...cycle.decisions].reverse()" :key="decision.id"><th scope="row">{{ decision.plan.symbol }}<small>{{ date(decision.at) }}</small></th><td class="paper-reason">{{ decision.plan.reason }}<small>{{ decision.note }}</small></td><td>{{ orderStatus[decision.status] }}</td></tr></tbody></table><div v-else-if="tab==='orders'" class="paper-record-empty">尚无决策，失败与弃权也会保留。</div>
        <template v-if="tab==='calls'"><ul v-if="state?.calls.some(c=>c.cycleId===cycle.id)" class="paper-gap-list"><li v-for="call in state!.calls.filter(c=>c.cycleId===cycle.id).slice().reverse()" :key="call.id"><time>{{ date(call.at) }}</time>{{ call.model }} · {{ {reserved:'已预留',complete:'已完成',failed:'失败'}[call.status] }}<p>{{ call.note }}</p></li></ul><div v-else class="paper-record-empty">暂无调用。每轮预留两次额度，失败也保留占用。</div></template>
        <template v-if="tab==='gaps'"><ul v-if="cycle.gaps.length" class="paper-gap-list"><li v-for="(gap,i) in cycle.gaps" :key="i"><time>{{ date(gap.at) }}</time>{{ gap.reason }}</li></ul><div v-else class="paper-record-empty">尚未记录运行中断；这不代表行情连续性已得到证明。</div></template>
      </div>
      <footer class="paper-footer"><span>{{ state?.note }}</span><details><summary>成本与执行口径</summary><p>每边手续费假设 {{ cycle.policy.feeBps }}bps、额外滑点 {{ cycle.policy.slippageBps }}bps。使用可见盘口，不模拟真实排队；止损跳空可能超过预设预算。资金费按公布记录核对，延迟或缺失显示待结算。应用关闭、休眠和断网不保证退出执行。</p><p>模拟历史只在本机保存，开启新周期不会清空旧交易；不直接相加不同本金周期的收益率。</p></details></footer>
    </template>
    <ConfirmDialog v-if="creating" title="开启新的模拟周期" confirm-label="确认预算并开始模拟" :busy="busy" @close="creating=false" @confirm="start"><div class="paper-start-form"><label for="paper-capital">虚拟本金 · USDT</label><div class="segmented"><button v-for="value in ['1000','10000']" :key="value" :aria-pressed="capital===value" @click="capital=value">{{ Number(value).toLocaleString() }}</button></div><AppTextInput id="paper-capital" v-model="capital" inputmode="decimal" placeholder="100–1,000,000"/><label>模型调用硬预算</label><AppSelect v-model="calls" label="每日模型调用预算" :options="[{value:4,label:'最多 4 次 / 24h'},{value:12,label:'最多 12 次 / 24h'},{value:24,label:'最多 24 次 / 24h'}]"/><p>每轮最多两次调用，每次输出上限 1,200 tokens，间隔至少 30 分钟。调用可能产生真实模型费用，实际账单未知；虚拟本金不会支付这些费用。</p><p>点击确认会启用所选模型的自动调用。旧周期停止开仓，持仓等待有效报价结算；旧历史全部保留。</p><p v-if="error" role="alert" class="research-error">{{ error }}</p></div></ConfirmDialog>
    <ConfirmDialog v-if="endConsent" title="结束本周期？" confirm-label="停止开仓并等待结算" :busy="busy" @close="endConsent=false" @confirm="mode('settling')"><p>取消待成交订单。已持仓使用之后的有效盘口模拟平仓，资金费补齐后归档；数据不足时保留待结算，不强行填零。</p></ConfirmDialog>
    <ConfirmDialog v-if="tradeDetail" :title="`${tradeDetail.symbol} · 模拟成交依据`" confirm-label="返回列表" @close="tradeDetail=null" @confirm="tradeDetail=null"><p>{{ cycle?.decisions.find(d=>d.id===tradeDetail!.id)?.plan.reason }}</p><p>冻结决策 {{ date(cycle?.decisions.find(d=>d.id===tradeDetail!.id)?.at||0) }} · 策略 {{ tradeDetail.policyVersion }}</p><p>开仓报价 {{ tradeDetail.entry.quoteId }} · {{ date(tradeDetail.entry.quoteAt) }}；采用对手盘口与可见深度，额外滑点已计入成交价格。</p><p>已计手续费 {{ amount(tradeDetail.fees) }}；资金费 {{ amount(tradeDetail.funding,true) }}，核对至 {{ date(tradeDetail.fundingThrough) }}。</p><details><summary>查看冻结证据</summary><p v-for="fact in cycle?.decisions.find(d=>d.id===tradeDetail!.id)?.plan.evidence" :key="fact.id">{{ fact.label }}：{{ fact.value }} {{ fact.unit }} · {{ date(fact.observedAt) }} · {{ fact.source }}</p></details><p>仅本地模拟。原始证据、委托状态与成交不可由后续策略改写。</p></ConfirmDialog>
  </main>
</template>
<style scoped>
.paper-page{padding:0 28px;flex:1;min-height:0;display:flex;flex-direction:column;overflow:auto;scrollbar-width:thin}.paper-actions{display:flex;align-items:center;gap:10px}.paper-intro{margin:auto;text-align:center;max-width:560px;display:flex;flex-direction:column;align-items:center;gap:22px;color:var(--muted)}.paper-intro h2{font-size:26px;letter-spacing:-.8px;color:var(--text)}.paper-intro p{font-size:13px;line-height:1.9}.paper-intro small{font-size:11px}.paper-steps{display:flex;gap:20px;font-size:11px;padding:18px 0;border-block:1px solid var(--border)}.paper-status{display:flex;align-items:center;gap:12px;font-size:11px;color:var(--muted);padding-bottom:16px}.paper-status>.paper-actions{margin-left:auto}.paper-kpis{display:grid;grid-template-columns:1.1fr 1fr 1fr .9fr;padding:20px 0;border-block:1px solid var(--border);gap:24px}.paper-kpis>div{display:flex;flex-direction:column;gap:9px}.paper-kpis span,.paper-kpis small{font-size:11px;color:var(--muted)}.paper-kpis strong{font-size:27px;font-weight:600;letter-spacing:-.8px;font-variant-numeric:tabular-nums}.paper-kpis strong small{font-size:18px}.paper-insight{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(240px,1fr);padding:20px 0;gap:28px}.paper-chart{min-width:0}.paper-chart-label{display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:10px}.paper-chart-label h2,.paper-agent h2{font-size:12px;font-weight:600;color:var(--text)}.paper-chart svg{height:120px;width:100%;color:var(--brand);margin-top:8px}.paper-chart-empty{height:128px;display:grid;place-items:center;color:var(--muted);font-size:11px;background:linear-gradient(transparent 49%,var(--border) 50%,transparent 51%)}.paper-agent{border-left:1px solid var(--border);padding-left:24px}.paper-agent h2{display:flex;align-items:center;gap:8px;margin-bottom:15px}.paper-agent h2>span{height:6px;width:6px;border-radius:50%;background:var(--muted)}.paper-agent p{font-size:11px;line-height:1.8;color:var(--muted)}.paper-agent>div{display:flex;gap:16px;align-items:center;margin:11px 0;font-size:11px}.paper-agent strong{font-weight:500}.paper-agent span,.paper-agent small{font-size:10px;color:var(--muted)}.paper-agent small{display:block;line-height:1.7;margin-top:18px}.paper-pulse{background:var(--brand)!important;animation:paperPulse 1.4s ease-in-out infinite}@keyframes paperPulse{50%{opacity:.35}}.paper-tabs{display:flex;gap:24px;border-bottom:1px solid var(--border);flex-shrink:0}.paper-tabs button{background:none;border:0;border-bottom:2px solid transparent;padding:12px 0;color:var(--muted);font-size:12px}.paper-tabs button[aria-pressed=true]{color:var(--text);border-color:var(--brand)}.paper-records{min-height:150px;flex:1;overflow:auto}.paper-table{width:100%;border-collapse:collapse;font-size:11px;font-variant-numeric:tabular-nums}.paper-table th,.paper-table td{padding:13px 10px;border-bottom:1px solid var(--border);text-align:right;vertical-align:middle;white-space:nowrap}.paper-table th:first-child,.paper-table td:first-child{text-align:left;padding-left:0}.paper-table th{font-weight:550}.paper-table thead th{color:var(--muted);font-size:10px;font-weight:400}.paper-table small{display:block;font-size:10px;color:var(--muted);padding-top:6px}.paper-table .paper-reason{white-space:normal;text-align:left;max-width:500px;line-height:1.8}.paper-record-empty{padding:36px 0;text-align:center;color:var(--muted);font-size:12px}.paper-gap-list{padding:16px 0;list-style:none;display:grid;gap:16px;font-size:11px}.paper-gap-list time{margin-right:20px;color:var(--muted)}.paper-footer{border-top:1px solid var(--border);padding:12px 0 16px;display:flex;gap:20px;justify-content:space-between;font-size:10px;color:var(--muted);line-height:1.7}.paper-footer details{max-width:420px}.paper-footer summary{cursor:pointer;white-space:nowrap}.paper-start-form{display:flex;flex-direction:column;gap:12px}.paper-start-form label{font-size:12px;color:var(--text)}.paper-start-form p{font-size:12px;line-height:1.8}.paper-start-form .segmented{align-self:flex-start}.paper-start-form .ui-select-trigger{width:100%}@media(max-width:1000px){.paper-page{padding:0 20px}.paper-kpis{gap:16px}.paper-kpis strong{font-size:23px}.paper-actions{gap:6px}.paper-table th,.paper-table td{padding-inline:6px}}@media(prefers-reduced-motion:reduce){.paper-pulse{animation:none}}
</style>
